function PhotoPicker() {
  useEffect(() => { ImagePicker.requestCameraPermissionsAsync(); }, []);
  return (
    <View>
      <Text style={{fontSize: 10, color: '#999'}}>Add a photo</Text>
      <TouchableOpacity onPress={pick} style={{width: 28, height: 28}}>
        <Image source={cameraIcon} style={{width: 28, height: 28}} />
      </TouchableOpacity>
      <TouchableOpacity onPress={() => setEnabled(!enabled)}>
        <View style={{width: 20, height: 20, backgroundColor: enabled ? 'green' : 'red'}} />
      </TouchableOpacity>
    </View>
  );
}
